source("commons.R")

library("jsonlite")
library("sets")

DATA_FILE <- paste0(RESULT_DIR_OUT, "/data_wfc_report.csv")

# Read the content of the fault_categories_<version>.json file in the current folder.
# The file is expected to have a list of object, where each object all contains the same fields.
# Need to extract information for the fields 'code' (numeric) and 'id' (string).
# Return a data structure to contain such info, with one row per object.
faultCategories <- function(){

  files <- list.files(pattern = "^fault_categories_.*\\.json$")
  if (length(files) == 0) {
    stop("No fault_categories_<version>.json file found in the current folder.")
  }
  if (length(files) > 1) {
    stop("Multiple fault_categories_<version>.json files found. Please specify a version.")
  }
  file <- files[1]

  data <- jsonlite::fromJSON(file, simplifyDataFrame = TRUE)

  # Extract 'code' (numeric) and 'id' (string) fields
  result <- data.frame(
    code = as.numeric(data$code),
    id   = as.character(data$id),
    stringsAsFactors = FALSE
  )

  return(result)
}

CATEGORIES <- faultCategories()

# Based on what currently defined in WFC
CODES <- sort(CATEGORIES$code)
IDS <- sort(CATEGORIES$id)


# Given a file system 'path', look at all of its ancestor folder names until one is found that is named exactly as 'base'.
# If none exists, throw meaningful error message.
# Otherwise, based on the numeric 'level', return the subfolder name starting from 'base' down at that level.
# For example, if level=0, then what returned is necessarely equal to 'base'.
# In the case of path=C:/foo/bar/tests/a/b/whatever and base="tests", then:
# level=0  returns 'tests'
# level=1  returns 'a'
# level=2  returns 'b'
# Negative levels, or levels too high, should throw a meaningful exception.
targetFolderName <- function(path, base, level) {

  if (length(level) != 1 || is.na(level) ||
    level < 0 || level != as.integer(level)) {
    stop("'level' must be a non-negative integer.")
  }

  folders <- character()
  current <- path

  repeat {
    folders <- c(basename(current), folders)

    if (basename(current) == base)
      break

    parent <- dirname(current)

    if (parent == current)
      stop(sprintf("Could not find folder '%s' in path '%s'.",
                   base, path))

    current <- parent
  }

  if (level >= length(folders))
    stop(sprintf("Level %d is too high below '%s'.", level, base))

  folders[level+1]
}

## Gather data from all report.json files into a single CSV file
init <- function() {

  TABLE <- DATA_FILE
  unlink(TABLE)

  tryCatch({
    sink(TABLE, append = TRUE, split = TRUE)

    cat("SUT,TOOL,ENDPOINTS")

    for(x in CODES){
      # T: "type", number of endpoints with that fault type detected
      # C: "context", number of unque faults based on context information, can be several per endpoint, so C >= T
      cat(",","T",x,",C",x,sep="")
    }

    cat("\n")

    for (path in sort(list.files(RESULT_DIR_IN, recursive = TRUE, full.names = TRUE, pattern = "^.*report.json$"))) {

      sut  <- targetFolderName(path, "tests", 2)
      tool <-  targetFolderName(path, "tests", 1)
      cat(sut, ",", tool, sep = "")

      json <- fromJSON(path)

      endpoints <- length(json$problemDetails$rest$endpointIds)
      cat(",", endpoints,sep="")

      faults <- json$faults$foundFaults

      ft_vec <- character()
      fc_vec <- character()

      n_faults <- nrow(faults)

      if( !( is.null(faults) || (is.vector(faults) && length(faults) == 0) || (is.data.frame(faults) && n_faults  == 0)) ) {
        for (i in seq_len(n_faults)) {

          row_i <- faults[i, ]
          operationId <- row_i$operationId
          k <- row_i$faultCategories[[1]]

          n_k <- nrow(k)

          for(j in seq_len(n_k)){

            row_kj <- k[j, ]

            code <- row_kj$code
            context <- row_kj$context

            faultType <- paste(code,operationId)
            faultContext <- paste(faultType,context)

            ft_vec <- c(ft_vec, faultType)
            fc_vec <- c(fc_vec, faultContext)
          }
        }
      }

      faultTypes <- unique(ft_vec)
      faultContexts <- unique(fc_vec)

      for(code in CODES){
        types <- Filter(function(e) startsWith(e,as.character(code)) , faultTypes)
        contexts <- Filter(function(e) startsWith(e,as.character(code)) , faultContexts)

        cat(",",length(types),",",length(contexts),sep="")
      }

      cat("\n", sep = "")
    }
  }, finally = {
    sink()
  })
}

foundCodes <- function(dt){
  found <- CODES[sapply(CODES, function(code) {
    col_name <- paste0("T", code)
    if (col_name %in% names(dt)) {
      col_data <- dt[[col_name]]
      return(is.numeric(col_data) && any(col_data > 0, na.rm = TRUE))
    } else {
      return(FALSE)
    }
  })]
  return(found)
}


## Create a Latex table to visualize the report.json results, per SUT, for a specific TOOL.
## As we have way too many fault categories, need to specify a subselection
tableSingleToolReport <- function(toolName, codes, dataFilePath, tableName){

  dt <- read.csv(dataFilePath, header = T)
  suts <- sort(unique(dt$SUT))

  printAverage <- function(cov) {
    covAvg <- mean(cov)
    cat(formatC(covAvg, digits = 1, format = "f"))
  }

  printSummaryComparison <- function(data, lambda) {
    E <- data[, 1] # endpoints
    cat(" & ")
    cat(formatC(lambda(E), digits = 0, format = "f"), sep = "")

    for(i in 2:ncol(data)){
      x <- data[, i]
      cat(" & ")
      cat(formatC(lambda(x), digits = 1, format = "f"), sep = "")
    }
  }

  FAULTS <- intersect(foundCodes(dt), codes)

  TABLE <- paste0(GENERATED_FILES, "/", tableName)
  unlink(TABLE)
  sink(TABLE, append = TRUE, split = TRUE)

  tMask <- dt$TOOL == toolName

  tryCatch({
    cat("\\begin{tabular}{lr")
    cat(paste(rep("r",length(FAULTS)),collapse=""),"}\\\\ \n")
    cat("\\toprule \n")
    cat(" SUT & \\#Endp  ")
    for(code in FAULTS){
      cat(" & F",code,sep="")
    }
    cat("  \\\\ \n", sep = "")
    cat("\\midrule \n")

    averages <- matrix(nrow = length(suts), ncol = 1+length(FAULTS)*1) # endpoint, + type (no context), per code
    ncounters <- rep(0, times=(1+length(FAULTS)) )

    for (i in seq_along(suts)) {

      if(i %% 2 == 0){
        cat("\\rowcolor{gray!30} ")
      }

      sut <- suts[[i]]
      cat("\\emph{", sut, "}", sep = "")
      sMask <- (dt$SUT == sut) & tMask

      endpoints <- unique(dt$ENDPOINTS[sMask])
      cat(" & ")
      cat(endpoints)
      averages[i,1] <- endpoints
      ncounters[1] <- ncounters[1] + 1

      j <- 2

      for(code in FAULTS){

        types <- dt[[paste0("T", code)]][sMask]
        contexts <- dt[[paste0("C", code)]][sMask]

        if(mean(types) == 0){
          cat(" & ")
          averages[i,j] <- 0
          j <- j+1
        } else {
          x <- types
          cat(" & ")
          printAverage(x)
          averages[i,j] <- mean(x)
          ncounters[j] <- ncounters[j] + 1
          j <- j+1
        }
      }

      cat(" \\\\ \n")
    }
    cat("\\midrule \n")
    cat("Mean ")
    printSummaryComparison(averages, mean)
    cat(" \\\\ \n")

    cat("Median ")
    printSummaryComparison(averages, median)
    cat(" \\\\ \n")

    cat("Sum ")
    printSummaryComparison(averages, sum)
    cat(" \\\\ \n")

    cat("\\midrule \n")
    cat("\\#SUTs")
    for(i in 1:length(ncounters)){
      x <- ncounters[i]
      cat(" & ")
      cat(formatC(x, digits = 0, format = "f"), sep = "")
    }
    cat(" \\\\ \n")

    cat("\\bottomrule \n")
    cat("\\end{tabular} \n")

  }, finally = {
    sink()
  })
}

### COPIED
TEX <- "tex"
MD  <- "md"
toolLabel <- function(id, format){
  #verifyFormat(format)
  if(format == TEX){
    return(paste0("\\",id))
  }
  if(format == MD){
    return(paste0("__",id,"__"))
  }
}
# TODO could be generalized with lambdas, and moved to tables-comparisons.R
######################################
# This functions reads the content of CSV file located at 'dataFilePath'.
# Then, it creates a table, with name 'tableFileName', either in Markdown or Latex format, based on input 'format'.
# The first output column is called "Category".
# Its content are the string values stored in CATEGORIES$id, one per row.
# As such values most likely contain '_', those should be properly escaped (taking into account escape constrains of Latex and Markdown).
# The second column is called Code, and contains the numerical values of CATEGORIES$code.
# The raws should be sorted based on Code.
# Note that all codes and ids are unique, and there is alwasy a 1-1 mapping between the two.
# Then, there is a column for each unique value of the data column TOOL, sorted, which contains string values (name of tools).
# The row contents are based on the following format 'X (Y)', where:
# - 'id' is the value under "Category"
# - 'tool' is the value from TOOL for that column
# - 'code' is the numerical code retrieved from CATEGORIES$code where CATEGORIES$id is matching 'id'
# - X is a number derived from the column in CSV file named T'code', eg, T100, computed this way:
# --- should only count rows where TOOL is equal to 'tool' variable
# --- for each distinct value of SUT, compute the average for that T'code'
# --- sum these average values per SUT, which will be the final X
# --- when printing this mean average, use 1-digit precision, eg., 3.4 and not 3.42
# - Y is based on the same column T'code', but computed like this:
# --- count the number of distinct SUT values for which there is at least one T'code' entry being non-zero
# In these rows, X represents the agregated sum of the average number of faults of type 'code', whereas Y is the number of
# SUTs for which at least one fault was found at least once.
# After a horizontal midline, the last row should contain the length/size N of CATEGORIES$id for the column Category
# (starting with 'Total: N').
# The column Code can have its value empty, whereas each other column should be the sum of the X values. Ignore Y in this last row.
# When outputting the table in Latex, every second row should be in grey.
multiToolFaultComparison <- function(
  dataFilePath, # the OS path where the CSV file containing the data is stored
  tableFileName,  # output file name, without file ending type
  format # either "tex" or "md"
){
  # verifyFormat(format)
  dt <- read.csv(dataFilePath, stringsAsFactors = FALSE)
  # verifyDataFrame(dt)

  if(! exists("CATEGORIES")){
    stop("CATEGORIES not defined")
  }

  categories <- CATEGORIES[order(CATEGORIES$code), ]
  tools <- sort(unique(dt$TOOL))

  escapeLabel <- function(s, format){
    gsub("_", "\\_", s, fixed = TRUE)
  }

  computeCell <- function(tool, code){
    col <- paste0("T", code)
    mask <- dt$TOOL == tool
    values <- dt[[col]][mask]
    suts <- dt$SUT[mask]

    if(length(values) == 0){
      return(list(x = 0, y = 0))
    }

    # per-SUT averages, then sum them
    perSut <- tapply(values, suts, mean, na.rm = TRUE)
    x <- sum(perSut, na.rm = TRUE)

    # count distinct SUTs with at least one non-zero entry
    y <- 0
    for(s in unique(suts)){
      v <- values[suts == s]
      if(any(v != 0, na.rm = TRUE)){
        y <- y + 1
      }
    }
    return(list(x = x, y = y))
  }

  TABLE <- paste0(GENERATED_FILES, "/", tableFileName, ".", format)
  unlink(TABLE)
  sink(TABLE, append = TRUE, split = TRUE)

  tryCatch({

    if(format == TEX){
      cat("\\begin{tabular}{ l r ", paste(rep("r ", length(tools)), collapse = ''), " }\\\\ \n", sep = "")
      cat("\\toprule \n")
      z <- function(x){return(paste(" & ", toolLabel(tools[x], format)))}
      cat("Category & Code ", paste(lapply(1:length(tools), z), collapse = ''), " \\\\ \n", sep = "")
      cat("\\midrule \n")
    } else if(format == MD){
      z <- function(x){return(paste(" | ", toolLabel(tools[x], format)))}
      cat("| __Category__ | __Code__ ", paste0(lapply(1:length(tools), z), collapse = ''), " | \n", sep = "")
      cat("| :--- | ---: ", paste(rep("|---:", length(tools)), collapse = ""), " | \n", sep = "")
    }

    totals <- rep(0, length(tools))

    for(j in 1:nrow(categories)){
      id   <- categories$id[j]
      code <- categories$code[j]

      if(format == TEX){
        if(j %% 2 == 0){
          cat("\\rowcolor{gray!30} ")
        }
        cat("\\emph{", escapeLabel(id, format), "}", sep = "")
      }
      if(format == MD){
        cat("| _", escapeLabel(id, format), "_", sep = "")
      }

      # Code column
      if(format == TEX) cat(" & ")
      if(format == MD)  cat(" | ")
      cat(code)

      for(i in 1:length(tools)){
        t <- tools[i]
        cell <- computeCell(t, code)

        if(format == TEX) cat(" & ")
        if(format == MD)  cat(" | ")

        cat(formatC(cell$x, digits = 1, format = "f"))
        cat(" (", cell$y, ")", sep = "")

        totals[i] <- totals[i] + cell$x
      }

      if(format == TEX) cat(" \\\\ \n")
      if(format == MD)  cat(" | \n")
    }

    if(format == TEX) cat("\\midrule \n")

    if(format == TEX) cat("Total: ", nrow(categories), sep = "")
    if(format == MD)  cat("| __Total: ", nrow(categories), "__", sep = "")

    if(format == TEX) cat(" & ")
    if(format == MD)  cat(" | ")

    for(i in 1:length(tools)){
      if(format == TEX) cat(" & ")
      if(format == MD)  cat(" | ")
      cat(formatC(totals[i], digits = 1, format = "f"))
    }

    if(format == TEX) cat(" \\\\ \n")
    if(format == MD)  cat(" | \n")

    if(format == TEX){
      cat("\\bottomrule \n")
      cat("\\end{tabular} \n")
    }

  }, finally = {
    sink()
  })
}


all <- function(){
  DATA_FILE <- paste0(RESULT_DIR_OUT, "/data_wfc_report.csv")

  multiToolFaultComparison(DATA_FILE, "comparisonFaults","tex")
  multiToolFaultComparison(DATA_FILE, "comparisonFaults","md")
}
